{
  "unit": 40,
  "font": "sans",
  "points": {
    "B": {"at": [0, 0], "label": "B", "dot": true, "labelDir": "sw"},
    "D": {"at": [0, 6], "label": "D", "dot": true, "labelDir": "w"},
    "N": {"move": {"from": "D", "d": 2, "deg": 90}, "label": "N", "dot": false},
    "C": {"polar": {"center": "B", "r": 9.2, "deg": 32}, "label": "C", "dot": true, "labelDir": "se"},
    "A": {"polar": {"center": "D", "r": 6, "deg": 140}, "label": "A", "dot": true, "labelDir": "nw"}
  },
  "elements": [
    {
      "type": "segment",
      "from": "B",
      "to": "N",
      "style": "dashed"
    },
    {
      "type": "arrow",
      "from": "D",
      "to": "N",
      "kind": "pointer"
    },
    {
      "type": "polygon",
      "points": ["A", "B", "C", "D"],
      "closed": true,
      "style": "solid"
    },
    {
      "type": "segment",
      "from": "B",
      "to": "D",
      "style": "solid"
    },
    {
      "type": "angle",
      "at": "B",
      "a": "D",
      "b": "C",
      "label": "30°",
      "r": 1.5
    },
    {
      "type": "angle",
      "at": "C",
      "a": "B",
      "b": "D",
      "label": "85°",
      "r": 1.2
    },
    {
      "type": "text",
      "at": {"along": {"from": "A", "to": "B", "t": 0.5}},
      "text": "14.5 m",
      "anchor": "sw"
    },
    {
      "type": "text",
      "at": {"along": {"from": "A", "to": "D", "t": 0.5}},
      "text": "6 m",
      "anchor": "ne"
    },
    {
      "type": "text",
      "at": {"along": {"from": "C", "to": "D", "t": 0.5}},
      "text": "9 m",
      "anchor": "ne"
    }
  ]
}

